function hydrateTeacherAliases(emp = {}) {
  emp.EXPERENCE_NURSE = emp.EXPERENCE_NURSE || emp.EXPERIENCE_NURSE || '';
  emp.EXPERIENCE_NURSE = emp.EXPERIENCE_NURSE || emp.EXPERENCE_NURSE || '';
  emp.EXPERENCE_TEACH = emp.EXPERENCE_TEACH || emp.EXPERIENCE_TEACH || '';
  emp.EXPERIENCE_TEACH = emp.EXPERIENCE_TEACH || emp.EXPERENCE_TEACH || '';
  emp.TIME_REMAINING = firstDisplayValue(emp.TIME_REMAINING, emp.REMAINING_TIME, emp.DAYS_REMAINING, emp.LICENSE_TIME_REMAINING);
  emp.RENEWAL_NOTICE_DATE = firstDisplayValue(emp.RENEWAL_NOTICE_DATE, emp.NOTICE_DATE, emp.RENEWAL_DATE, emp.LICENSE_RENEWAL_NOTICE_DATE);
  emp.LICENSE_STATUS = firstDisplayValue(emp.LICENSE_STATUS, emp.STATUS_LICENSE);
  return emp;
}

function firstDisplayValue(...values) {
  const value = values.find(item => {
    const text = String(item ?? '').trim();
    return text && text !== '-';
  });
  return value || '';
}

function formatDateDistance(fromDate, toDate) {
  const from = new Date(fromDate.getFullYear(), fromDate.getMonth(), fromDate.getDate());
  const to = new Date(toDate.getFullYear(), toDate.getMonth(), toDate.getDate());
  if (to < from) return 'หมดอายุแล้ว';

  let years = to.getFullYear() - from.getFullYear();
  let months = to.getMonth() - from.getMonth();
  let days = to.getDate() - from.getDate();

  if (days < 0) {
    days += new Date(to.getFullYear(), to.getMonth(), 0).getDate();
    months -= 1;
  }
  if (months < 0) {
    years -= 1;
    months += 12;
  }

  return [`${years} ปี`, `${months} เดือน`, `${days} วัน`].join(' ');
}

function getDashboardFilteredRows() {
  const status = document.getElementById('dashboardStatusFilter')?.value || '';
  const department = document.getElementById('dashboardDepartmentFilter')?.value || '';
  const workStatus = document.getElementById('dashboardWorkStatusFilter')?.value || '';
  const active = document.getElementById('dashboardActiveFilter')?.value || '';

  return employees.filter(emp => {
    if (!isPersonnelRecord(emp)) return false;
    const matchStatus = !status || (status === 'EXECUTIVE' ? isExecutivePerson(emp) : getPersonnelGroup(emp) === status);
    const matchDepartment = !department || normalizeDepartment(emp.DEPARTMENT) === normalizeDepartment(department);
    const matchWorkStatus = !workStatus || normalizeFilterText(emp.WORK_STATUS || 'ปฏิบัติงาน') === normalizeFilterText(workStatus);
    const matchActive = !active || String(emp.ACTIVE_SYS).trim().toLowerCase() === active;
    return matchStatus && matchDepartment && matchWorkStatus && matchActive;
  });
}

