function renderChartJs(id, type, items, extraOptions = {}) {
  items = Array.isArray(items) ? items : [];
  const canvas = document.getElementById(id);
  if (!canvas || typeof Chart === 'undefined') return;
  if (dashboardCharts[id]) dashboardCharts[id].destroy();
  if (type === 'doughnut') {
    prepareDashboardDoughnutCanvas(canvas);
  }
  const labels = items.map(item => item.label);
  const values = items.map(item => item.value);
  const colors = items.map(item => item.color || '#3f7ee8');
  dashboardCharts[id] = new Chart(canvas, {
    type,
    data: {
      labels,
      datasets: [{
        label: extraOptions.datasetLabel || 'จำนวน',
        data: values,
        backgroundColor: colors,
        borderColor: type === 'doughnut'
          ? items.map(item => item.borderColor || '#ffffff')
          : (type === 'line' ? '#143f68' : '#ffffff'),
        borderWidth: type === 'doughnut' ? items.map(item => item.borderWidth || 2) : 0,
        offset: type === 'doughnut' ? items.map(item => item.offset || 0) : 0,
        borderRadius: type === 'bar' ? 6 : 0,
        maxBarThickness: 54,
        tension: .34,
        fill: type === 'line',
        hoverOffset: type === 'doughnut' ? 8 : 0
      }]
    },
    options: {
      responsive: true,
      devicePixelRatio: getDashboardChartDpr(),
      maintainAspectRatio: type === 'doughnut',
      aspectRatio: getDashboardChartAspectRatio(type, extraOptions),
      cutout: type === 'doughnut' ? '56%' : undefined,
      interaction: { mode: 'nearest', intersect: true },
      onHover: (event, elements) => {
        if (event?.native?.target) event.native.target.style.cursor = elements.length ? 'pointer' : 'default';
      },
      layout: { padding: type === 'doughnut' ? { top: 8, right: 8, bottom: 8, left: 8 } : { top: 24, right: 28, bottom: 0, left: 8 } },
      indexAxis: extraOptions.indexAxis || 'x',
      plugins: {
        legend: { display: type === 'doughnut' || Boolean(extraOptions.showLegend), position: 'bottom', labels: { boxWidth: type === 'doughnut' ? 16 : 10, padding: type === 'doughnut' ? 14 : 8, font: { family: 'Noto Sans Thai', weight: 800, size: type === 'doughnut' ? 13 : 12 } } },
        tooltip: getDashboardTooltipOptions(extraOptions),
        datalabels: getDashboardDataLabelOptions(type, extraOptions)
      },
      scales: type === 'doughnut' ? {} : {
        x: { beginAtZero: true, grace: type === 'bar' ? '18%' : 0, grid: { color: '#e1e7ef' }, ticks: { font: { family: 'Noto Sans Thai', weight: 700, size: 12 } } },
        y: { beginAtZero: true, grace: type === 'bar' ? '18%' : 0, grid: { color: '#e1e7ef' }, ticks: { precision: 0, font: { family: 'Noto Sans Thai', weight: 700, size: 12 } } }
      },
      onClick: (event, elements, chart) => {
        const points = getDashboardChartClickPoints(event, elements, chart);
        if (!points.length) return;
        const index = getDashboardChartPointIndex(points[0]);
        const item = items[index];
        if (!item) return;
        if (typeof extraOptions.onItemClick === 'function') extraOptions.onItemClick(item.filter || {}, item);
        else applyDashboardDrilldown(item.filter || {});
      }
    }
  });
}

function prepareChartJsCanvas(canvas) {
  if (!canvas) return;
  const rect = canvas.getBoundingClientRect();
  if (rect.width > 0 && rect.height > 0) {
    canvas.width = Math.round(rect.width);
    canvas.height = Math.round(rect.height);
    canvas.style.width = `${Math.round(rect.width)}px`;
    canvas.style.height = `${Math.round(rect.height)}px`;
  }
}

