/* =========================================
   TABLE
========================================= */

function renderTable() {

  const q = document
    .getElementById('searchInput')
    .value
    .toLowerCase()
    .trim();

  const status = document
    .getElementById('statusFilter')
    .value;

  const department = document
    .getElementById('departmentFilter')
    .value;

  const active = document
    .getElementById('activeFilter')
    .value;

  const workStatus = document
    .getElementById('workStatusFilter')
    .value;

  const rows = (Array.isArray(employees) ? employees : []).filter(e => {
    if (!isPersonnelRecord(e)) return false;

    const text = [
      e.FULL_NAME,
      e.EMAIL,
      e.POSITION,
      e.DEPARTMENT,
      formatWorkGroup(e.WORK_GROUP),
      e.WORK_STATUS
    ]
      .join(' ')
      .toLowerCase();

    const matchSearch =
      !q || text.includes(q);

    const matchStatus =
      !status ||
      (status === 'EXECUTIVE'
        ? isExecutivePerson(e)
        : getPersonnelGroup(e) === status);

    const matchDepartment =
      !department || [e.DEPARTMENT, e.DEPARTMENT_NAME, e.DEPARTMENT_ID]
        .some(value => normalizeDepartment(value) === normalizeDepartment(department));

    const matchActive =
      !active ||
      String(e.ACTIVE_SYS).trim().toLowerCase() === active;

    const matchWorkStatus =
      !workStatus || normalizeFilterText(e.WORK_STATUS || 'ปฏิบัติงาน') === normalizeFilterText(workStatus);

    return (
      matchSearch &&
      matchDepartment &&
      matchStatus &&
      matchActive &&
      matchWorkStatus
    );
  }).sort((a, b) => {
    if (!status) {
      const groupCompare = getGroupRank(a) - getGroupRank(b);
      if (groupCompare !== 0) return groupCompare;

      if (isExecutivePerson(a) && isExecutivePerson(b)) {
        return compareExecutivePeople(a, b);
      }

      return normalizeFilterText(a.FULL_NAME)
        .localeCompare(normalizeFilterText(b.FULL_NAME), 'th');
    }

    return status === 'EXECUTIVE'
      ? compareExecutivePeople(a, b)
      : comparePersonnelPeople(a, b);
  });

  renderActiveFilterBar({
    status,
    department,
    active,
    workStatus,
    query: q,
    count: rows.length
  });

  const tbody =
    document.getElementById('employeeTable');

  tbody.innerHTML = '';

  if (rows.length === 0) {

    tbody.innerHTML = `
      <tr>
        <td colspan="7" style="text-align:center;color:#6b7280;">
          ไม่พบข้อมูล
        </td>
      </tr>
    `;

    return;
  }

  let currentGroup = '';
  const shouldShowGroupRows = Boolean(status);
  const groupCounts = shouldShowGroupRows
    ? (Array.isArray(rows) ? rows : []).reduce((counts, item) => {
        const title = getDisplayGroupTitle(item, status);
        counts[title] = (counts[title] || 0) + 1;
        return counts;
      }, {})
    : {};

  rows.forEach(e => {
    const groupTitle = getDisplayGroupTitle(e, status);
    if (shouldShowGroupRows && groupTitle !== currentGroup) {
      currentGroup = groupTitle;
      tbody.innerHTML += `
        <tr class="table-group-row">
          <td colspan="7">
            <div class="table-group-title">
              <span>${escapeHtml(groupTitle)}</span>
              <small>${groupCounts[groupTitle] || 0} คน</small>
            </div>
          </td>
        </tr>
      `;
    }

    const isActive =
      String(e.ACTIVE_SYS).toLowerCase() === 'true';

    const photo =
      e.PIC ||
      'https://cdn-icons-png.flaticon.com/512/149/149071.png';

    tbody.innerHTML += `
      <tr class="clickable-row" data-action="view" data-person-id="${escapeAttr(e.PERSON_ID)}">

        <td>
          <img
            src="${photo}"
            style="
              width:52px;
              height:52px;
              border-radius:16px;
              object-fit:cover;
              border:1px solid #e5e7eb;
            "
          >
        </td>

        <td>
          <span class="badge ${isActive ? 'active' : 'inactive'}">
            ${isActive ? 'ใช้งาน' : 'ปิดใช้งาน'}
          </span>
        </td>

        <td>
          <button type="button" class="name-link" data-action="view" data-person-id="${escapeAttr(e.PERSON_ID)}">
            ${escapeHtml(e.FULL_NAME || '-')}
          </button>
          <small>รหัสบุคลากร: ${escapeHtml(e.PERSON_ID || '-')}</small>
        </td>

        <td>${escapeHtml(formatWorkGroup(e.WORK_GROUP) || '-')}</td>

        <td>${escapeHtml(e.POSITION || '-')}</td>

        <td>${escapeHtml(e.DEPARTMENT || '-')}</td>

        <td>${escapeHtml(e.EMAIL || '-')}</td>

      </tr>
    `;
  });
}

function setupTableActions() {
  const table = document.getElementById('employeeTable');
  if (!table) return;

  table.addEventListener('click', event => {
    const target = event.target.closest('[data-action][data-person-id]');
    if (!target || !table.contains(target)) return;

    event.stopPropagation();
    const personId = target.dataset.personId || '';

    if (target.dataset.action === 'view') {
      viewEmployee(personId);
      return;
    }
  });
}

function renderActiveFilterBar(state) {
  const bar = document.getElementById('activeFilterBar');
  if (!bar) return;

  const chips = [
    ['ส่วนงาน', getFilterSelectText('statusFilter')],
    ['หน่วยงาน', getFilterSelectText('departmentFilter')],
    ['การปฏิบัติงาน', getFilterSelectText('workStatusFilter')],
    ['ระบบ', getFilterSelectText('activeFilter')]
  ];

  if (state.query) {
    chips.push(['ค้นหา', state.query]);
  }

  bar.innerHTML = `
    <span class="active-filter-label">กำลังแสดง:</span>
    ${chips.map(([label, value]) => `
      <span class="filter-chip">
        <strong>${escapeHtml(label)}:</strong>${escapeHtml(value || 'ทั้งหมด')}
      </span>
    `).join('')}
    <span class="active-filter-count">พบ ${state.count} รายการ</span>
  `;
}

function getFilterSelectText(id) {
  const el = document.getElementById(id);
  if (!el) return '';
  const selected = el.options[el.selectedIndex];
  return selected ? selected.textContent.trim() : '';
}

/* =========================================
   FORM
========================================= */
autoEducation();

function getEducationEditRows() {
  return Array.from(document.querySelectorAll('.education-edit-table tbody tr'));
}

function markEducationRowsDirty() {
  educationRowsDirty = true;
}

function resetEducationRowsDirty() {
  educationRowsDirty = false;
}

function createEducationEditRow(data = {}, editable = true) {
  const tbody = document.getElementById('educationRowsBody');
  if (!tbody) return null;

  const row = document.createElement('tr');
  row.dataset.educationId = data.educationId || data.EDUCATION_ID || '';
  row.innerHTML = `
    <td>
      <select data-education-field="level" onchange="markEducationRowsDirty(); autoEducation(); ensureEducationTrailingRow();">
        <option value="">เลือก</option>
        ${EDUCATION_LEVELS.map(([value, label]) => `
          <option value="${escapeAttr(value)}"${String(data.level || '').toUpperCase() === value ? ' selected' : ''}>${escapeHtml(label)}</option>
        `).join('')}
      </select>
    </td>
    <td><input data-education-field="degree" value="${escapeAttr(data.degree || '')}" oninput="markEducationRowsDirty(); autoEducation(); ensureEducationTrailingRow();" /></td>
    <td><input data-education-field="major" value="${escapeAttr(data.major || '')}" oninput="markEducationRowsDirty(); autoEducation(); ensureEducationTrailingRow();" /></td>
    <td><input data-education-field="institution" value="${escapeAttr(data.institution || '')}" oninput="markEducationRowsDirty(); ensureEducationTrailingRow();" /></td>
    <td><input data-education-field="year" value="${escapeAttr(data.year || '')}" oninput="markEducationRowsDirty(); ensureEducationTrailingRow();" /></td>
    <td><button type="button" class="row-edit-switch" data-education-row-toggle aria-label="เปิดแก้ไขวุฒิการศึกษา"></button></td>
  `;
  tbody.appendChild(row);
  setEducationRowEditable(row, editable);
  return row;
}

function setEducationRowEditable(row, editable) {
  if (!row) return;
  row.classList.toggle('is-locked', !editable);
  row.querySelectorAll('input, select').forEach(input => {
    if (input.tagName === 'SELECT') {
      input.disabled = !editable;
      input.title = '';
    } else {
      input.readOnly = !editable;
    }
  });

  const button = row.querySelector('[data-education-row-toggle]');
  if (button) {
    button.classList.toggle('is-on', editable);
    button.setAttribute('aria-pressed', String(editable));
  }
}

function rowHasEducationValue(row) {
  return Array.from(row.querySelectorAll('input, select'))
    .some(input => String(input.value || '').trim());
}

function readEducationRow(row) {
  const get = field => row.querySelector(`[data-education-field="${field}"]`)?.value || '';
  return {
    educationId: row.dataset.educationId || '',
    level: get('level'),
    degree: get('degree').trim(),
    major: get('major').trim(),
    institution: get('institution').trim(),
    year: get('year').trim()
  };
}

function educationRowHasContent(item) {
  return Boolean(String(item.degree || item.major || item.institution || item.year || '').trim());
}

function getEducationLevelLabel(level) {
  const normalized = String(level || '').trim().toUpperCase();
  const found = EDUCATION_LEVELS.find(item => item[0] === normalized);
  return found ? found[1] : (level || '');
}

function getEducationLevelOrder(level) {
  const normalized = String(level || '').trim().toUpperCase();
  if (normalized === 'DOCTORAL') return 3;
  if (normalized === 'MASTER') return 2;
  if (normalized === 'BACHELOR') return 1;
  return 0;
}

function normalizeEducationDuplicateText(value) {
  return String(value || '').trim().replace(/\s+/g, ' ').toLowerCase();
}

function getEducationDuplicateKey(row) {
  return [
    normalizeEducationDuplicateText(row.level).toUpperCase(),
    normalizeEducationDuplicateText(row.degree),
    normalizeEducationDuplicateText(row.major),
    normalizeEducationDuplicateText(row.institution),
    normalizeEducationDuplicateText(row.year)
  ].join('|');
}

function dedupeEducationRows(rows) {
  const seen = new Set();
  return (rows || []).filter(row => {
    const id = String(row.educationId || row.EDUCATION_ID || '').trim();
    const key = id ? `id:${id}` : `content:${getEducationDuplicateKey(row)}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function findDuplicateEducationRow(rows) {
  const seen = new Set();
  return rows.find(row => {
    const key = getEducationDuplicateKey(row);
    if (seen.has(key)) return true;
    seen.add(key);
    return false;
  }) || null;
}

function collectEducationRows() {
  return dedupeEducationRows(getEducationEditRows()
    .map(readEducationRow)
    .filter(educationRowHasContent));
}

function applyEducationRowsToPayload(payload) {
  const rows = collectEducationRows();
  payload.EDUCATION_ROWS = JSON.stringify(rows);

  const firstByLevel = level => rows.find(row => String(row.level || '').toUpperCase() === level) || {};
  const bachelor = firstByLevel('BACHELOR');
  const master = firstByLevel('MASTER');
  const doctoral = firstByLevel('DOCTORAL');
  const other = firstByLevel('OTHER');

  payload.BACHELOR_DEGREE = bachelor.degree || '';
  payload.BACHELOR_MAJOR = bachelor.major || '';
  payload.BACHELOR_DEGREES_INST_ID = bachelor.institution || '';
  payload.BACHELOR_DEGREES_YEAR = bachelor.year || '';
  payload.MASTER_DEGREE = master.degree || '';
  payload.MASTER_MAJOR = master.major || '';
  payload.MASTER_DEGREES_INST_ID = master.institution || '';
  payload.MASTER_DEGREES_YEAR = master.year || '';
  payload.DOCTORAL_DEGREE = doctoral.degree || '';
  payload.DOCTORAL_MAJOR = doctoral.major || '';
  payload.DOCTORAL_DEGREES_OTHER_ID = doctoral.institution || '';
  payload.DOCTORAL_DEGREES_YEAR = doctoral.year || '';
  payload.MASTER_DEGREES_OTHER_NAME = other.degree || '';
  payload.MASTER_DEGREES_OTHER_MAJOR_ID = other.major || '';
  payload.MASTER_DEGREES_OTHER_INST_ID = other.institution || '';
  payload.MASTER_DEGREES_OTHER_YEAR = other.year || '';
}

function removeEducationRowsFromPayload(payload) {
  [
    'EDUCATION_ROWS',
    'HIGHEST_EDUCATION',
    'NURSING_FIELD',
    'BACHELOR_DEGREE',
    'BACHELOR_MAJOR',
    'BACHELOR_DEGREES_INST_ID',
    'BACHELOR_DEGREES_YEAR',
    'MASTER_DEGREE',
    'MASTER_MAJOR',
    'MASTER_DEGREES_INST_ID',
    'MASTER_DEGREES_YEAR',
    'DOCTORAL_DEGREE',
    'DOCTORAL_MAJOR',
    'DOCTORAL_DEGREES_OTHER_ID',
    'DOCTORAL_DEGREES_YEAR',
    'MASTER_DEGREES_OTHER_NAME',
    'MASTER_DEGREES_OTHER_MAJOR_ID',
    'MASTER_DEGREES_OTHER_INST_ID',
    'MASTER_DEGREES_OTHER_YEAR'
  ].forEach(field => {
    delete payload[field];
  });
}

function resetEducationEditRows(rows = [], forceEditable = false) {
  const tbody = document.getElementById('educationRowsBody');
  if (!tbody) return;

  tbody.innerHTML = '';
  const sourceRows = Array.isArray(rows) && rows.length ? rows : [{}];
  sourceRows.forEach(row => {
    createEducationEditRow(row, forceEditable || !educationRowHasContent(row));
  });
  ensureEducationTrailingRow();
  resetEducationRowsDirty();
}

function ensureEducationTrailingRow() {
  const rows = getEducationEditRows();
  const last = rows[rows.length - 1];
  if (!last || rowHasEducationValue(last)) {
    createEducationEditRow({}, true);
  }
}

function getEducationRowsFromEmployee(emp = {}) {
  if (Array.isArray(emp.EDUCATION_ROWS) && emp.EDUCATION_ROWS.length) {
    return dedupeEducationRows(emp.EDUCATION_ROWS.map(row => ({
      level: row.DEGREE_LEVEL || row.level || '',
      educationId: row.EDUCATION_ID || row.educationId || '',
      degree: row.DEGREE_NAME || row.degree || '',
      major: row.MAJOR || row.major || '',
      institution: row.INSTITUTION_NAME || row.INSTITUTION_OTHER_NAME || row.INSTITUTION_ID || row.institution || '',
      year: row.GRAD_YEAR_BE || row.year || ''
    })).filter(educationRowHasContent));
  }

  return [
    { level: 'BACHELOR', degree: emp.BACHELOR_DEGREE, major: emp.BACHELOR_MAJOR, institution: emp.BACHELOR_DEGREES_INST_ID, year: emp.BACHELOR_DEGREES_YEAR },
    { level: 'MASTER', degree: emp.MASTER_DEGREE, major: emp.MASTER_MAJOR, institution: emp.MASTER_DEGREES_INST_ID, year: emp.MASTER_DEGREES_YEAR },
    { level: 'DOCTORAL', degree: emp.DOCTORAL_DEGREE, major: emp.DOCTORAL_MAJOR, institution: emp.DOCTORAL_DEGREES_OTHER_ID, year: emp.DOCTORAL_DEGREES_YEAR },
    { level: 'OTHER', degree: emp.MASTER_DEGREES_OTHER_NAME, major: emp.MASTER_DEGREES_OTHER_MAJOR_ID, institution: emp.MASTER_DEGREES_OTHER_INST_ID, year: emp.MASTER_DEGREES_OTHER_YEAR }
  ].filter(educationRowHasContent);
}

function setupEducationRowToggles() {
  document.addEventListener('click', event => {
    const button = event.target.closest('[data-education-row-toggle]');
    if (!button) return;

    const row = button.closest('tr');
    const isEditable = button.classList.contains('is-on');
    setEducationRowEditable(row, !isEditable);
    if (isEditable) return;
    if (!row.dataset.educationId) markEducationRowsDirty();
  });
}

