function setupPersonIdAutoGenerate() {
  const citizenInput = document.getElementById('CITIZEN_ID');
  if (!citizenInput) return;
  citizenInput.addEventListener('input', updateGeneratedPersonIdPreview);
  citizenInput.addEventListener('change', updateGeneratedPersonIdPreview);
}

function updateGeneratedPersonIdPreview() {
  const personInput = document.getElementById('PERSON_ID');
  if (!personInput || !personInput.readOnly) return;
  personInput.value = buildNextPersonIdPreview(document.getElementById('CITIZEN_ID')?.value || '');
}

function buildNextPersonIdPreview(citizenId) {
  const digits = String(citizenId || '').replace(/\D/g, '');
  if (digits.length < 3) return '';

  const yearBe = String(new Date().getFullYear() + 543);
  const prefix = `NS${yearBe}`;
  const maxSeq = (Array.isArray(employees) ? employees : []).reduce((max, emp) => {
    const match = String(emp.PERSON_ID || '').trim().match(new RegExp(`^${prefix}(\\d{3})_\\d{3}$`));
    return match ? Math.max(max, Number(match[1] || 0)) : max;
  }, 0);

  return `${prefix}${String(maxSeq + 1).padStart(3, '0')}_${digits.slice(-3)}`;
}

