async function viewEmployee(personId) {
  personId = String(personId || '').trim();
  if (!personId) {
    showToast('ไม่พบรหัสบุคลากร');
    showPage('personnel');
    return;
  }

  if (!canAccessPerson(personId)) {
    showToast('ไม่มีสิทธิ์เข้าถึงข้อมูลบุคลากรรายนี้');
    return;
  }

  const emp = await getFullEmployeeForAction(personId).catch(err => {
    console.error(err);
    showToast(err.message || 'โหลดข้อมูลบุคลากรไม่สำเร็จ');
    return null;
  });

  if (!emp) {
    showToast('ไม่พบข้อมูล');
    showPage('personnel');
    return;
  }
  if (!String(emp.PERSON_ID || '').trim()) {
    showToast('ข้อมูลบุคลากรรายนี้ไม่สมบูรณ์');
    showPage('personnel');
    return;
  }
  hydrateTeacherAliases(emp);

  const photo =
    emp.PIC ||
    'https://cdn-icons-png.flaticon.com/512/149/149071.png';

  document.getElementById('detailTitle').textContent =
    emp.FULL_NAME || 'รายละเอียดบุคลากร';

  document.getElementById('detailSubtitle').textContent =
    `${formatWorkGroup(emp.WORK_GROUP) || '-'} | ${emp.POSITION || '-'} | ${emp.DEPARTMENT || '-'}`;

  const detailEditBtn = document.getElementById('detailEditBtn');
  if (detailEditBtn) detailEditBtn.dataset.personId = personId;

  const isTeacher = getPersonnelGroup(emp) === 'อาจารย์';
  const researchRows = getResearchByPerson(personId);
  const employeeRows = [
    [
      ['กลุ่มงาน', formatWorkGroup(emp.WORK_GROUP)],
      ['ประเภทการจ้าง', emp.EMPLOYMENT_TYPE],
      ['เลขที่พนักงาน', emp.EMPLOYEE_NO]
    ],
    [
      ['ตำแหน่ง', emp.POSITION],
      ['หน่วยงานภายใน', emp.DEPARTMENT]
    ]
  ];

  employeeRows.push([
    ['วันที่เริ่มงาน', formatDateForDisplay(emp.START_DATE_CE)],
    ['ปีงบประมาณเริ่มงาน', emp.START_FISCAL_YEAR],
    ['สถานะการทำงาน', emp.WORK_STATUS],
    ['อายุงาน', formatWorkTenure(emp.START_DATE_CE)]
  ]);

  const educationRows = getEducationTableRows(emp);
  const licenseInfo = getLicenseDerivedInfo(emp.PERMIT_CARD_CODE, emp.PERMIT_EXP);

  const employeeSection = renderDetailRowsSection('ข้อมูลพนักงาน', employeeRows);
  const licenseSection = isTeacher
    ? renderDetailRowsSection('ใบประกอบวิชาชีพ', [
      [
        ['เลขที่ใบประกอบวิชาชีพ', emp.PERMIT_CARD_CODE],
        ['วันหมดอายุ', formatDateForDisplay(emp.PERMIT_EXP)]
      ],
      [
        ['เวลาคงเหลือ', licenseInfo.timeRemaining],
        ['วันที่แจ้งเตือนต่ออายุ', licenseInfo.renewalNoticeDate],
        ['สถานะใบประกอบ', licenseInfo.licenseStatus]
      ]
    ])
    : '';
  const educationSection = renderEducationDetailTable(emp, educationRows) +
    (isTeacher ? renderTeacherExperienceSection(emp) : '');
  const researchSection = renderResearchDetailSection(researchRows);

  document.getElementById('detailContent').innerHTML = `
    <div class="detail-profile">
      <div class="detail-photo-box">
        <img class="detail-photo" id="detailPhotoPreview" src="${escapeAttr(photo)}" alt="">
        <button type="button" class="detail-photo-edit" onclick="document.getElementById('detailPhotoInput')?.click()">
          เปลี่ยนรูป
        </button>
        <input type="file" id="detailPhotoInput" accept="image/*" class="hidden" onchange="uploadDetailPhoto(event, '${escapeAttr(personId)}')">
      </div>
      <div>
        <h3 class="detail-name">${escapeHtml(emp.FULL_NAME || '-')}</h3>
        <p class="detail-meta">
          รหัสบุคลากร: ${escapeHtml(emp.PERSON_ID || '-')}<br>
          เลขบัตรประชาชน: ${escapeHtml(emp.CITIZEN_ID || '-')}<br>
          ${escapeHtml(emp.EMAIL || '-')}<br>
          วันเกิด: ${escapeHtml(formatBirthDate(emp) || '-')}<br>
          ${renderDetailBadge(emp.ACTIVE_SYS, emp.WORK_STATUS)}
        </p>
      </div>
    </div>

    ${renderDetailTabs([
      ['detail-employee', 'ข้อมูลพนักงาน', employeeSection],
      ['detail-license', 'ใบประกอบวิชาชีพ', licenseSection],
      ['detail-education', 'การศึกษา', educationSection],
      ['detail-research', 'ผลงานวิจัย', researchSection]
    ])}
  `;

  document
    .getElementById('detailPage')
    .classList.remove('hidden');
  showPage('detail');
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function getResearchByPerson(personId) {
  return researchItems
    .filter(item => String(item.PERSON_ID || '').trim() === String(personId || '').trim())
    .sort((a, b) => {
      const yearA = parseInt(a['YEAR ค.ศ'] || a.YEAR || a['ปี พ.ศ.'], 10) || 0;
      const yearB = parseInt(b['YEAR ค.ศ'] || b.YEAR || b['ปี พ.ศ.'], 10) || 0;
      return yearB - yearA;
    });
}

function renderResearchDetailSection(items) {
  if (!items.length) return '';

  return `
    <div class="detail-section detail-section--research">
      <h3>ผลงานวิจัย / วิชาการ</h3>
      <div class="research-list">
        ${items.map(renderResearchDetailItem).join('')}
      </div>
    </div>
  `;
}

function renderResearchDetailItem(item) {
  const link = String(item.LINK || '').trim();
  const title = firstResearchValue(item, ['TITLE', 'ชื่อเรื่อง']) || '-';
  const year = firstResearchValue(item, ['YEAR ค.ศ', 'YEAR', 'ปี พ.ศ.']);
  const meta = [
    firstResearchValue(item, ['JOURNAL']),
    year,
    firstResearchValue(item, ['ตีพิมพ์', 'สถานะ']),
    firstResearchValue(item, ['TYPE']),
    firstResearchValue(item, ['INDEX_STATUS']),
    firstResearchValue(item, ['Level'])
  ]
    .filter(Boolean)
    .join(' | ');
  const fund = [
    firstResearchValue(item, ['ทุน']),
    firstResearchValue(item, ['แหล่งทุน']),
    formatResearchMoney(firstResearchValue(item, ['จำนวนเงิน']))
  ].filter(Boolean).join(' | ');
  const note = [
    firstResearchValue(item, ['สาขาวิชา']),
    firstResearchValue(item, ['ref'])
  ].filter(Boolean).join(' | ');

  return `
    <article class="research-item">
      <div class="detail-item">
        <span class="detail-label">ชื่อเรื่อง</span>
        <div class="detail-value research-title">
          ${link ? `<a href="${escapeAttr(link)}" target="_blank" rel="noopener">${escapeHtml(title)}</a>` : escapeHtml(title)}
        </div>
      </div>
      <div class="detail-item">
        <span class="detail-label">วารสาร/ปี/ระดับ</span>
        <div class="detail-value">${escapeHtml(meta || '-')}</div>
      </div>
      ${fund ? `
        <div class="detail-item">
          <span class="detail-label">ทุน</span>
          <div class="detail-value">${escapeHtml(fund)}</div>
        </div>
      ` : ''}
      ${note ? `
        <div class="detail-item">
          <span class="detail-label">สาขา/อ้างอิง</span>
          <div class="detail-value">${escapeHtml(note)}</div>
        </div>
      ` : ''}
    </article>
  `;
}

function firstResearchValue(item, keys) {
  for (const key of keys) {
    const value = item && item[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}

function formatResearchMoney(value) {
  if (value === undefined || value === null || String(value).trim() === '') return '';
  const number = Number(String(value).replace(/,/g, ''));
  if (!isNaN(number)) return `${number.toLocaleString('th-TH')} บาท`;
  return value;
}

function renderDetailTabs(items) {
  const tabs = (items || []).filter(item => String(item[2] || '').trim() !== '');
  if (!tabs.length) return '';

  return `
    <div class="hrm-tabs detail-tabs" data-tab-group="detail">
      <div class="hrm-tab-list">
        ${tabs.map((item, index) => `
          <button
            type="button"
            class="hrm-tab-button${index === 0 ? ' active' : ''}"
            data-tab-target="${escapeAttr(item[0])}"
          >
            ${escapeHtml(item[1])}
          </button>
        `).join('')}
      </div>
      <div class="hrm-tab-panels">
        ${tabs.map((item, index) => `
          <div class="hrm-tab-panel${index === 0 ? ' active' : ''}" data-tab-panel="${escapeAttr(item[0])}">
            ${item[2]}
          </div>
        `).join('')}
      </div>
    </div>
  `;
}

function closeDetail() {
  showPage('personnel');
}

function closeForm() {

  document
    .getElementById('modal')
    .classList.add('hidden');
}

/* =========================================
   EDIT
========================================= */

async function editEmployee(personId) {
  if (!canAccessPerson(personId)) {
    showToast('ไม่มีสิทธิ์แก้ไขข้อมูลบุคลากรรายนี้');
    return;
  }

  let emp = await getFullEmployeeForAction(personId).catch(err => {
    console.error(err);
    showToast(err.message || 'โหลดข้อมูลสำหรับแก้ไขไม่สำเร็จ');
    return null;
  });

  if (!emp) {
    showToast('ไม่พบข้อมูล');
    return;
  }
  hydrateTeacherAliases(emp);

  document
    .getElementById('employeeForm')
    .reset();

  fields.forEach(field => {

    const el =
      document.getElementById(field);

    if (!el) return;

    let value = emp[field] ?? '';

    if (field === 'ACCOUNT_STATUS') {
      value =
        String(value).toUpperCase() === 'INACTIVE'
          ? 'INACTIVE'
          : 'ACTIVE';
    }

    if (
      (field === 'START_DATE_CE' || field === 'PERMIT_EXP' || field === 'RESIGN_DATE') &&
      value
    ) {
      value = formatDateForInput(value);
    }

    el.value = value;
  });

  const birthInput = document.getElementById('BIRTHDATE_TEXT');
  if (birthInput) {
    birthInput.value = formatBirthDateInput(emp);
  }

  const workAgeEl =
    document.getElementById('WORK_AGE');

  if (workAgeEl) {
    workAgeEl.value = formatWorkTenure(emp.START_DATE_CE) || emp.WORK_AGE || '';
  }

  setDepartmentFromEmployee(emp);
  setInputValue('TIME_REMAINING', emp.TIME_REMAINING || '');
  setInputValue('RENEWAL_NOTICE_DATE', formatDateForDisplay(emp.RENEWAL_NOTICE_DATE) || '');
  setInputValue('LICENSE_STATUS', emp.LICENSE_STATUS || '');

setActiveStatus(String(emp.ACTIVE_SYS).toLowerCase() !== 'false');
setWorkStatus(emp.WORK_STATUS || 'ปฏิบัติงาน');
autoFullName();
autoBirthText();
autoEducation();
resetEducationEditRows(getEducationRowsFromEmployee(emp), false);
activateFormTab('form-1');

  if (emp.PIC) {

    document.getElementById('photoPreview').src =
      emp.PIC;

    document.getElementById('photoPreview').style.display =
      'block';

    document.getElementById('photoText').style.display =
      'none';

  } else {

    document.getElementById('photoPreview').style.display =
      'none';

    document.getElementById('photoText').style.display =
      'block';
  }

  document
    .getElementById('modalTitle')
    .textContent = 'แก้ไขข้อมูลบุคลากร';
  document
    .getElementById('PERSON_ID')
    .readOnly = true;
  document
    .getElementById('modal')
    .dataset.mode = 'edit';

  toggleTeacherSection();

  document
    .getElementById('modal')
    .classList.remove('hidden');
}

window.editEmployee = editEmployee;
window.editCurrentDetail = editCurrentDetail;
if (typeof showDetail === 'function') window.showDetail = showDetail;
window.savePhotoOnly = savePhotoOnly;
window.uploadDetailPhoto = uploadDetailPhoto;

/* =========================================
   SAVE
========================================= */

async function submitForm(event) {

  event.preventDefault();

  if (isEmployeeSaving) {
    showToast('กำลังบันทึกข้อมูล กรุณารอสักครู่');
    return;
  }

  const validation = validateEmployeeFormBeforeSave();
  if (!validation.ok) {
    activateFormTab(validation.tab);
    showToast(validation.message);
    setTimeout(() => {
      if (validation.field) validation.field.focus();
    }, 80);
    return;
  }

  const payload = buildEmployeePayloadForSave({ includeEducationRows: educationRowsDirty, allowCreate: true });

  const saveBtn =
    document.getElementById('saveBtn');

  isEmployeeSaving = true;
  saveBtn.disabled = true;
  saveBtn.dataset.originalText = saveBtn.dataset.originalText || saveBtn.textContent;
  saveBtn.textContent = 'กำลังบันทึก...';

  showToast('กำลังบันทึกข้อมูล...');

  try {

    const res =
      await apiPost('save', payload);

    if (!res.success) {

      showToast(
        res.message || 'บันทึกไม่สำเร็จ'
      );

      return;
    }

    const savedPersonCode = String(res.data?.person_code || res.data?.PERSON_ID || '').trim();
    if (savedPersonCode) {
      payload.PERSON_ID = savedPersonCode;
      const personInput = document.getElementById('PERSON_ID');
      if (personInput) personInput.value = savedPersonCode;
    }

    showToast(
      res.message || 'บันทึกข้อมูลสำเร็จ'
    );

    closeForm();

    reloadAfterSave();

  } catch (err) {

    console.error(err);

    if (String(err && err.message || '').indexOf('Failed to fetch') >= 0) {
      closeForm();
      showToast('บันทึกข้อมูลแล้ว กำลังรีเฟรชหน้า...');
      setTimeout(() => window.location.reload(), 900);
    } else {
      showToast(err.message || 'เชื่อมต่อ API ไม่สำเร็จ');
    }
  } finally {
    isEmployeeSaving = false;
    saveBtn.disabled = false;
    saveBtn.textContent = saveBtn.dataset.originalText || 'บันทึกข้อมูล';
  }
}

function buildEmployeePayloadForSave(options = {}) {
  const payload = {};
  syncDepartmentFields();
  autoBirthText();

  fields.forEach(field => {
    const el = document.getElementById(field);
    if (!el) return;
    payload[field] = el.value.trim();
  });

  if (options.allowCreate && document.getElementById('modal')?.dataset.mode !== 'edit') {
    payload.PERSON_ID_PREVIEW = payload.PERSON_ID || '';
    payload.PERSON_ID = '';
    payload.AUTO_PERSON_CODE = 'TRUE';
  }

  payload.FULL_NAME = document.getElementById('FULL_NAME').value;
  payload.BIRTHDATE_TEXT = document.getElementById('BIRTHDATE_TEXT').value;
  payload.BIRTH_DATE = formatDateISOForSave(payload.BIRTHDATE_TEXT);

  if (options.includeEducationRows) {
    applyEducationRowsToPayload(payload);
  } else {
    removeEducationRowsFromPayload(payload);
  }
  applyDerivedPayload(payload);
  normalizeDatePayloadForSave(payload);
  return payload;
}

async function saveCurrentFormSection() {
  if (isEmployeeSaving) {
    showToast('กำลังบันทึกข้อมูล กรุณารอสักครู่');
    return;
  }

  if (document.getElementById('modal')?.dataset.mode !== 'edit') {
    showToast('พนักงานใหม่ต้องบันทึกข้อมูลทั้งฟอร์มก่อน');
    return;
  }

  const sectionInfo = getActiveFormSaveSection();
  if (!sectionInfo.section) {
    showToast('ไม่พบหมวดข้อมูลที่กำลังเปิดอยู่');
    return;
  }

  const includeEducationRows = sectionInfo.section === 'education';
  if (includeEducationRows) {
    const educationValidation = validateEducationRowsForSave(isTeacherFormActive());
    if (!educationValidation.ok) {
      activateFormTab(educationValidation.tab);
      showToast(educationValidation.message);
      setTimeout(() => {
        if (educationValidation.field) educationValidation.field.focus();
      }, 80);
      return;
    }
  }

  const payload = filterEmployeePayloadForSection(
    buildEmployeePayloadForSave({ includeEducationRows, allowCreate: false }),
    sectionInfo
  );

  const saveSectionBtn = document.getElementById('saveSectionBtn');
  isEmployeeSaving = true;
  saveSectionBtn.disabled = true;
  saveSectionBtn.dataset.originalText = saveSectionBtn.dataset.originalText || saveSectionBtn.textContent;
  saveSectionBtn.textContent = 'กำลังบันทึก...';
  showToast('กำลังบันทึกหมวดนี้...');

  try {
    const res = await apiPost('saveSection', payload);
    if (!res.success) {
      showToast(res.message || 'บันทึกหมวดนี้ไม่สำเร็จ');
      return;
    }
    showToast(res.message || 'บันทึกหมวดนี้สำเร็จ');
    await reloadAfterSave();
  } catch (err) {
    console.error(err);
    showToast(err.message || 'เชื่อมต่อ API ไม่สำเร็จ');
  } finally {
    isEmployeeSaving = false;
    saveSectionBtn.disabled = false;
    saveSectionBtn.textContent = saveSectionBtn.dataset.originalText || 'บันทึกหมวดนี้';
  }
}

function getActiveFormSaveSection() {
  const activePanel = document.querySelector('#employeeForm .form-tabs .hrm-tab-panel.active');
  const tab = activePanel && activePanel.dataset.tabPanel || 'form-1';
  if (tab === 'form-2') return { section: 'employment', tab };
  if (tab === 'form-4') return { section: 'education', tab };
  if (tab === 'form-3') return { section: 'master', tab, group: 'license' };
  if (tab === 'form-teacher') return { section: 'master', tab, group: 'teacher' };
  if (tab === 'form-1') return { section: 'master', tab, group: 'person' };
  return { section: '', tab };
}

function filterEmployeePayloadForSection(payload, sectionInfo) {
  const keep = new Set(['PERSON_ID', 'section']);
  payload.section = sectionInfo.section;

  const byGroup = {
    person: [
      'CITIZEN_ID', 'PREFIX', 'FIRST_NAME', 'LAST_NAME', 'FULL_NAME', 'EMAIL',
      'BIRTHDATE_TEXT', 'BIRTH_DATE', 'BIRTH_DAY', 'BIRTH_MONTH', 'BIRTH_YEAR_BE',
      'PIC', 'ACCOUNT_STATUS', 'ACTIVE_EMPLOYEE'
    ],
    license: ['PERMIT_CARD_CODE', 'PERMIT_EXP'],
    teacher: ['ACADEMIC_POSITION', 'EXPERENCE_NURSE', 'EXPERIENCE_NURSE', 'EXPERENCE_TEACH', 'EXPERIENCE_TEACH', 'PROFICIENCY'],
    employment: [
      'EMPLOYEE_NO', 'EMPLOYMENT_TYPE', 'WORK_GROUP', 'POSITION', 'POSITION_ID',
      'DEPARTMENT_ID', 'DEPARTMENT', 'DEPARTMENT_NAME', 'START_DATE_CE',
      'START_FISCAL_YEAR', 'WORK_STATUS', 'RESIGN_DATE', 'RESIGN_FISCAL_YEAR',
      'ACCOUNT_STATUS', 'ACTIVE_EMPLOYEE', 'IS_EXECUTIVE', 'EXECUTIVE_ORDER',
      'สัญญาจ้าง'
    ],
    education: ['EDUCATION_ROWS', 'WORK_GROUP', 'NURSING_FIELD']
  };

  const fieldsForGroup = byGroup[sectionInfo.group || sectionInfo.section] || [];
  fieldsForGroup.forEach(field => keep.add(field));

  Object.keys(payload).forEach(key => {
    if (!keep.has(key)) delete payload[key];
  });
  return payload;
}

async function reloadAfterSave() {
  try {
    await loadData();
  } catch (err) {
    console.error(err);
    showToast('บันทึกแล้ว แต่โหลดข้อมูลใหม่ไม่สำเร็จ กรุณารีเฟรชหน้า');
  }
}

async function savePhotoOnly(options = {}) {
  const personId = document.getElementById('PERSON_ID')?.value.trim();
  const pic = document.getElementById('PIC')?.value.trim();
  const btn = document.getElementById('savePhotoOnlyBtn');
  const silentStart = Boolean(options.silentStart);
  const closeAfterSave = Boolean(options.closeAfterSave);

  if (!personId) {
    showToast('กรุณาเลือกบุคลากรก่อนบันทึกรูป');
    return;
  }
  if (!pic) {
    showToast('กรุณาอัปโหลดรูปภาพก่อนบันทึก');
    return;
  }

  if (btn) {
    btn.disabled = true;
    btn.dataset.originalText = btn.dataset.originalText || btn.textContent;
    btn.textContent = 'กำลังบันทึกรูป...';
  }

  if (!silentStart) showToast('กำลังบันทึกรูปภาพ...');

  try {
    const res = await apiPost('savePhoto', {
      PERSON_ID: personId,
      PIC: pic
    });

    if (!res.success) {
      showToast(res.message || 'บันทึกรูปไม่สำเร็จ');
      return;
    }

    showToast(res.message || 'บันทึกรูปภาพสำเร็จ');
    await loadData();
    if (closeAfterSave) closeForm();
  } catch (err) {
    console.error(err);
    showToast('เชื่อมต่อ API ไม่สำเร็จ');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = btn.dataset.originalText || 'บันทึกรูปอย่างเดียว';
    }
  }
}

function validateEmployeeFormBeforeSave() {
  clearEmployeeValidationState();

  const isTeacher = isTeacherFormActive();
  const isCreate = document.getElementById('modal')?.dataset.mode !== 'edit';
  const requiredGroups = [
    {
      tab: 'form-1',
      fields: [
        ['CITIZEN_ID', 'เลขบัตรประชาชน'],
        ['PREFIX', 'คำนำหน้า'],
        ['FIRST_NAME', 'ชื่อ'],
        ['LAST_NAME', 'นามสกุล'],
        ['EMAIL', 'อีเมล'],
        ['BIRTHDATE_TEXT', 'วันเดือนปีเกิด']
      ]
    },
    {
      tab: 'form-2',
      fields: [
        ['WORK_GROUP', 'ส่วนงาน'],
        ['EMPLOYMENT_TYPE', 'ประเภทการจ้าง'],
        ['EMPLOYEE_NO', 'เลขที่พนักงาน'],
        ['POSITION', 'ตำแหน่ง'],
        ['DEPARTMENT_ID', 'กลุ่มวิชา'],
        ['START_DATE_CE', 'วันที่เริ่มงาน']
      ]
    }
  ];

  if (!isCreate) {
    requiredGroups[0].fields.unshift(['PERSON_ID', 'รหัสบุคลากร']);
  }

  if (document.getElementById('WORK_STATUS')?.value === 'ลาออก') {
    requiredGroups[0].fields.push(['RESIGN_DATE', 'วันที่ลาออก']);
  }

  if (isTeacher) {
    requiredGroups.push(
      {
        tab: 'form-3',
        fields: [
          ['PERMIT_CARD_CODE', 'เลขที่ใบประกอบวิชาชีพ'],
          ['PERMIT_EXP', 'วันหมดอายุใบประกอบวิชาชีพ']
        ]
      },
      {
        tab: 'form-teacher',
        fields: [
          ['ACADEMIC_POSITION', 'ตำแหน่งทางวิชาการ'],
          ['EXPERENCE_NURSE', 'ประสบการณ์พยาบาล'],
          ['EXPERENCE_TEACH', 'ประสบการณ์สอน'],
          ['PROFICIENCY', 'ความเชี่ยวชาญ']
        ]
      }
    );
  }

  for (const group of requiredGroups) {
    const missing = [];
    let firstField = null;
    group.fields.forEach(([id, label]) => {
      const el = document.getElementById(id);
      if (!el || el.closest('.hidden')) return;
      if (!normalizeFilterText(el.value)) {
        missing.push(label);
        firstField = firstField || el;
        markFieldInvalid(el);
      }
    });
    if (missing.length) {
      return {
        ok: false,
        tab: group.tab,
        field: firstField,
        message: `กรอกข้อมูลไม่ครบ: ${missing.slice(0, 4).join(', ')}${missing.length > 4 ? '...' : ''}`
      };
    }
  }

  const citizenInput = document.getElementById('CITIZEN_ID');
  const citizenDigits = String(citizenInput?.value || '').replace(/\D/g, '');
  if (citizenInput && citizenDigits.length < 3) {
    markFieldInvalid(citizenInput);
    return {
      ok: false,
      tab: 'form-1',
      field: citizenInput,
      message: 'เลขบัตรประชาชนต้องมีอย่างน้อย 3 หลักท้ายเพื่อสร้าง person_code'
    };
  }

  const educationValidation = validateEducationRowsForSave(isTeacher);
  if (!educationValidation.ok) return educationValidation;

  return { ok: true };
}

function validateEducationRowsForSave(isTeacher) {
  const rows = collectEducationRows();
  if (isTeacher && !rows.length) {
    return {
      ok: false,
      tab: 'form-4',
      field: document.querySelector('#educationRowsBody select, #educationRowsBody input'),
      message: 'กรอกข้อมูลไม่ครบ: ต้องมีข้อมูลการศึกษาอย่างน้อย 1 แถว'
    };
  }

  const incomplete = rows.find(row =>
    !normalizeFilterText(row.level) ||
    !normalizeFilterText(row.degree) ||
    !normalizeFilterText(row.major) ||
    !normalizeFilterText(row.institution) ||
    !normalizeFilterText(row.year)
  );

  if (incomplete) {
    const editRow = getEducationEditRows().find(row => {
      const item = readEducationRow(row);
      return item.degree === incomplete.degree &&
        item.major === incomplete.major &&
        item.institution === incomplete.institution &&
        item.year === incomplete.year;
    });
    const firstEmpty = editRow && Array.from(editRow.querySelectorAll('select, input'))
      .find(input => !normalizeFilterText(input.value));
    if (firstEmpty) markFieldInvalid(firstEmpty);

    return {
      ok: false,
      tab: 'form-4',
      field: firstEmpty || document.querySelector('#educationRowsBody select, #educationRowsBody input'),
      message: 'กรอกข้อมูลไม่ครบ: แถวการศึกษาต้องมีระดับ วุฒิ สาขา สถาบัน และปีที่สำเร็จ'
    };
  }

  const duplicate = findDuplicateEducationRow(rows);
  if (duplicate) {
    const editRow = getEducationEditRows().find(row =>
      getEducationDuplicateKey(readEducationRow(row)) === getEducationDuplicateKey(duplicate)
    );
    const focusField = editRow?.querySelector('[data-education-field="degree"]') ||
      document.querySelector('#educationRowsBody select, #educationRowsBody input');
    if (focusField) markFieldInvalid(focusField);
    return {
      ok: false,
      tab: 'form-4',
      field: focusField,
      message: `พบข้อมูลการศึกษาซ้ำ: ${getEducationLevelLabel(duplicate.level)} ${[duplicate.degree, duplicate.major, duplicate.institution].filter(Boolean).join(' / ')}`
    };
  }

  const invalidYear = rows.find(row => !isValidGraduationYear(row.year));
  if (invalidYear) {
    const editRow = getEducationEditRows().find(row => {
      const item = readEducationRow(row);
      return item.year === invalidYear.year &&
        item.degree === invalidYear.degree &&
        item.major === invalidYear.major;
    });
    const yearField = editRow?.querySelector('[data-education-field="year"]') ||
      document.querySelector('#educationRowsBody [data-education-field="year"]');
    if (yearField) markFieldInvalid(yearField);
    return {
      ok: false,
      tab: 'form-4',
      field: yearField,
      message: 'ปีที่สำเร็จการศึกษาต้องเป็น พ.ศ. 2400-2700 เช่น 2558'
    };
  }

  return { ok: true };
}

function isValidGraduationYear(value) {
  const digits = String(value || '').replace(/\D/g, '');
  if (!digits) return false;
  const year = Number(digits);
  return Number.isFinite(year) && year >= 2400 && year <= 2700;
}

function isTeacherFormActive() {
  const workGroup = normalizeFilterText(document.getElementById('WORK_GROUP')?.value);
  const position = normalizeFilterText(document.getElementById('POSITION')?.value);
  return workGroup.indexOf('วิชาการ') >= 0 ||
    position === 'อาจารย์' ||
    isDeanPosition(position) ||
    position.indexOf('รองคณบดี') === 0 ||
    position === 'ผู้ช่วยคณบดี';
}

function markFieldInvalid(el) {
  el.classList.add('field-invalid');
  el.setAttribute('aria-invalid', 'true');
}

function clearEmployeeValidationState() {
  document.querySelectorAll('#employeeForm .field-invalid').forEach(el => {
    el.classList.remove('field-invalid');
    el.removeAttribute('aria-invalid');
  });
}

/* =========================================
   DELETE
========================================= */

async function deleteEmployee(personId) {
  if (isLimitedUser()) {
    showToast('บัญชี USER ไม่มีสิทธิ์ปิดใช้งานบุคลากร');
    return;
  }

  if (!canAccessPerson(personId)) {
    showToast('ไม่มีสิทธิ์ปิดใช้งานข้อมูลบุคลากรรายนี้');
    return;
  }

  const ok =
    confirm('ยืนยันการปิดใช้งานบุคลากรรายนี้?');

  if (!ok) return;

  showToast('กำลังปิดใช้งาน...');

  try {

    const res =
      await apiPost('delete', {
        personId
      });

    if (!res.success) {

      showToast(
        res.message || 'ดำเนินการไม่สำเร็จ'
      );

      return;
    }

    showToast(
      res.message || 'ปิดใช้งานเรียบร้อยแล้ว'
    );

    await loadData();

  } catch (err) {

    console.error(err);

    showToast('เชื่อมต่อ API ไม่สำเร็จ');
  }
}

/* =========================================
   TEACHER SECTION
========================================= */

function toggleTeacherSection() {
  const workGroup = document.getElementById('WORK_GROUP')?.value || '';
  const position = document.getElementById('POSITION')?.value || '';
  const isTeacher =
    workGroup.indexOf('วิชาการ') >= 0 ||
    position === 'อาจารย์' ||
    position.indexOf('คณบดี') >= 0 ||
    position.indexOf('ผู้ช่วยคณบดี') >= 0;

  const section =
    document.getElementById('teacherSection');
  const teacherOnlyBlocks =
    document.querySelectorAll('.teacher-only');

  if (!section) return;

  if (isTeacher) {

    section.classList.remove('hidden');
    teacherOnlyBlocks.forEach(el => el.classList.remove('hidden'));

  } else {

    section.classList.add('hidden');
    teacherOnlyBlocks.forEach(el => el.classList.add('hidden'));

    [
      'PERMIT_CARD_CODE',
      'PERMIT_EXP',
      'ACADEMIC_POSITION',
      'EXPERENCE_NURSE',
      'EXPERENCE_TEACH'
    ].forEach(id => {

      const el =
        document.getElementById(id);

      if (el) el.value = '';
    });
  }

  updateTeacherFormTab();
}

/* =========================================
   FULL NAME
========================================= */

function autoFullName() {

  const first =
    document.getElementById('FIRST_NAME').value || '';

  const last =
    document.getElementById('LAST_NAME').value || '';

  document.getElementById('FULL_NAME').value =
    `${first} ${last}`.trim();
}

/* =========================================
   BIRTH
========================================= */

function initBirthDropdowns() {
  syncBirthPartsFromText();
}

function autoBirthText() {
  const birthInput = document.getElementById('BIRTHDATE_TEXT');
  if (!birthInput) return;
  const parsed = parseDateValue(birthInput.value);
  if (parsed) {
    birthInput.value = formatDateBEForSheet(parsed);
  }
  syncBirthPartsFromText();
}

function syncBirthPartsFromText() {
  const parsed = parseDateValue(document.getElementById('BIRTHDATE_TEXT')?.value || '');
  const day = document.getElementById('BIRTH_DAY');
  const month = document.getElementById('BIRTH_MONTH');
  const year = document.getElementById('BIRTH_YEAR_BE');
  if (!day || !month || !year) return;
  day.value = parsed ? String(parsed.getDate()) : '';
  month.value = parsed ? getThaiMonthName(parsed.getMonth()) : '';
  year.value = parsed ? String(parsed.getFullYear() + 543) : '';
}

function initHrmThaiDateControls() {
  ['BIRTHDATE_TEXT', 'START_DATE_CE', 'PERMIT_EXP', 'RESIGN_DATE'].forEach(id => {
    const input = document.getElementById(id);
    if (!input) return;
    input.addEventListener('blur', () => {
      const parsed = parseDateValue(input.value);
      if (parsed) input.value = formatDateBEForSheet(parsed);
      if (id === 'BIRTHDATE_TEXT') syncBirthPartsFromText();
      if (id === 'START_DATE_CE' || id === 'RESIGN_DATE') updateDerivedFields();
      if (id === 'PERMIT_EXP') updateLicenseDerivedFields();
    });
  });
}

function openHrmThaiDatePicker(inputId) {
  const input = document.getElementById(inputId);
  if (!input) return;
  closeHrmThaiDatePicker();

  const selected = parseDateValue(input.value) || new Date();
  let year = selected.getFullYear();
  let month = selected.getMonth();

  const picker = document.createElement('div');
  picker.className = 'thai-date-picker-popover';
  picker.innerHTML = renderHrmThaiDatePickerContent(year, month, selected);
  document.body.appendChild(picker);

  const rect = input.getBoundingClientRect();
  picker.style.left = `${Math.min(rect.left + window.scrollX, window.scrollX + window.innerWidth - 330)}px`;
  picker.style.top = `${rect.bottom + window.scrollY + 8}px`;

  picker.addEventListener('mousedown', event => {
    event.stopPropagation();
  });
  picker.addEventListener('click', event => {
    event.stopPropagation();
    const dayBtn = event.target.closest('[data-thai-day]');
    const navBtn = event.target.closest('[data-thai-nav]');
    const todayBtn = event.target.closest('[data-thai-today]');

    if (dayBtn) {
      const d = new Date(year, month, Number(dayBtn.dataset.thaiDay));
      input.value = formatDateBEForSheet(d);
      input.dispatchEvent(new Event('change', { bubbles: true }));
      if (inputId === 'BIRTHDATE_TEXT') syncBirthPartsFromText();
      if (inputId === 'PERMIT_EXP') updateLicenseDerivedFields();
      closeHrmThaiDatePicker();
      return;
    }
    if (todayBtn) {
      const d = new Date();
      input.value = formatDateBEForSheet(d);
      input.dispatchEvent(new Event('change', { bubbles: true }));
      if (inputId === 'BIRTHDATE_TEXT') syncBirthPartsFromText();
      if (inputId === 'PERMIT_EXP') updateLicenseDerivedFields();
      closeHrmThaiDatePicker();
      return;
    }
    if (navBtn) {
      month += Number(navBtn.dataset.thaiNav);
      if (month < 0) { month = 11; year -= 1; }
      if (month > 11) { month = 0; year += 1; }
      picker.innerHTML = renderHrmThaiDatePickerContent(year, month, selected);
      return;
    }
  });

  picker.addEventListener('change', event => {
    event.stopPropagation();
    const monthSelect = event.target.closest('[data-thai-month]');
    const yearSelect = event.target.closest('[data-thai-year]');

    if (monthSelect) {
      month = Number(monthSelect.value);
      picker.innerHTML = renderHrmThaiDatePickerContent(year, month, selected);
      return;
    }
    if (yearSelect) {
      year = Number(yearSelect.value) - 543;
      picker.innerHTML = renderHrmThaiDatePickerContent(year, month, selected);
    }
  });

  setTimeout(() => {
    document.addEventListener('mousedown', closeHrmThaiDatePicker, { once: true });
  }, 0);
}

function closeHrmThaiDatePicker() {
  document.querySelectorAll('.thai-date-picker-popover').forEach(el => el.remove());
}

function renderHrmThaiDatePickerContent(year, month, selected) {
  const monthOptions = getThaiMonthNames().map((name, index) =>
    `<option value="${index}" ${index === month ? 'selected' : ''}>${name}</option>`
  ).join('');
  const beYear = year + 543;
  const yearOptions = Array.from({ length: 121 }, (_, index) => beYear - 80 + index)
    .map(value => `<option value="${value}" ${value === beYear ? 'selected' : ''}>${value}</option>`)
    .join('');
  const firstDay = new Date(year, month, 1).getDay();
  const maxDay = new Date(year, month + 1, 0).getDate();
  const dayCells = [];
  for (let i = 0; i < firstDay; i++) dayCells.push('<span></span>');
  for (let day = 1; day <= maxDay; day++) {
    const active = selected && selected.getFullYear() === year && selected.getMonth() === month && selected.getDate() === day;
    dayCells.push(`<button type="button" class="${active ? 'active' : ''}" data-thai-day="${day}">${day}</button>`);
  }
  return `
    <div class="thai-date-picker-head">
      <button type="button" data-thai-nav="-1">‹</button>
      <select data-thai-month>${monthOptions}</select>
      <select data-thai-year>${yearOptions}</select>
      <button type="button" data-thai-nav="1">›</button>
    </div>
    <div class="thai-date-picker-week"><span>อา</span><span>จ</span><span>อ</span><span>พ</span><span>พฤ</span><span>ศ</span><span>ส</span></div>
    <div class="thai-date-picker-grid">${dayCells.join('')}</div>
    <button type="button" class="thai-date-picker-today" data-thai-today>วันนี้</button>
  `;
}

function getThaiMonthNames() {
  return [
    'มกราคม',
    'กุมภาพันธ์',
    'มีนาคม',
    'เมษายน',
    'พฤษภาคม',
    'มิถุนายน',
    'กรกฎาคม',
    'สิงหาคม',
    'กันยายน',
    'ตุลาคม',
    'พฤศจิกายน',
    'ธันวาคม'
  ];
}

/* =========================================
   PHOTO
========================================= */

async function uploadPhoto(event) {

  const file =
    event.target.files[0];

  if (!file) return;

  showToast('กำลังอัปโหลดรูปภาพ...');

  try {
    const resized = await resizeImageForUpload(file);

    const res =
      await apiPost('uploadImage', {
        filename: resized.filename,
        contentType: resized.contentType,
        base64: resized.base64
      });

    if (!res.success) {
      showToast(res.message || 'อัปโหลดรูปภาพไม่สำเร็จ');
      return;
    }

    document.getElementById('PIC').value =
      res.url;

    const preview =
      document.getElementById('photoPreview');

    preview.src = resized.base64;
    preview.style.display = 'block';

    document.getElementById('photoText').style.display =
      'none';

    await savePhotoOnly({ silentStart: true, closeAfterSave: true });

  } catch (err) {
    console.error(err);
    showToast(err.message || 'เชื่อมต่อ API อัปโหลดรูปไม่สำเร็จ');
  }
}

async function uploadDetailPhoto(event, personId) {
  const file = event.target.files[0];
  if (!file) return;

  const currentPersonId = String(personId || '').trim();
  if (!currentPersonId) {
    showToast('ไม่พบรหัสบุคลากรสำหรับบันทึกรูป');
    return;
  }

  showToast('กำลังอัปโหลดและบันทึกรูปภาพ...');

  try {
    const resized = await resizeImageForUpload(file);
    const uploadRes = await apiPost('uploadImage', {
      filename: resized.filename,
      contentType: resized.contentType,
      base64: resized.base64
    });

    if (!uploadRes.success) {
      showToast(uploadRes.message || 'อัปโหลดรูปภาพไม่สำเร็จ');
      return;
    }

    const saveRes = await apiPost('savePhoto', {
      PERSON_ID: currentPersonId,
      PIC: uploadRes.url
    });

    if (!saveRes.success) {
      showToast(saveRes.message || 'บันทึกรูปไม่สำเร็จ');
      return;
    }

    const preview = document.getElementById('detailPhotoPreview');
    if (preview) preview.src = resized.base64;

    showToast(saveRes.message || 'บันทึกรูปภาพสำเร็จ');
    await loadData();
    const emp = employees.find(item => String(item.PERSON_ID || '').trim() === currentPersonId);
    if (emp) {
      emp.PIC = uploadRes.url;
      if (typeof showDetail === 'function') showDetail(currentPersonId);
    }
  } catch (err) {
    console.error(err);
    showToast(err.message || 'เชื่อมต่อ API อัปโหลดรูปไม่สำเร็จ');
  } finally {
    event.target.value = '';
  }
}

function resizeImageForUpload(file) {
  return new Promise((resolve, reject) => {
    if (!file.type || !file.type.startsWith('image/')) {
      reject(new Error('กรุณาเลือกไฟล์รูปภาพเท่านั้น'));
      return;
    }

    const reader = new FileReader();
    reader.onload = function() {
      const img = new Image();
      img.onload = function() {
        const maxSize = 1200;
        const scale = Math.min(1, maxSize / Math.max(img.width, img.height));
        const width = Math.max(1, Math.round(img.width * scale));
        const height = Math.max(1, Math.round(img.height * scale));

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);

        const base64 = canvas.toDataURL('image/jpeg', 0.84);
        const safeName = String(file.name || 'photo')
          .replace(/\.[^.]+$/, '')
          .replace(/[^\w.-]+/g, '_');

        resolve({
          filename: safeName + '.jpg',
          contentType: 'image/jpeg',
          base64
        });
      };
      img.onerror = function() {
        reject(new Error('อ่านไฟล์รูปภาพไม่สำเร็จ'));
      };
      img.src = reader.result;
    };
    reader.onerror = function() {
      reject(new Error('อ่านไฟล์ไม่สำเร็จ'));
    };
    reader.readAsDataURL(file);
  });
}

/* =========================================
   TOAST
========================================= */

function showToast(message) {

  const toast =
    document.getElementById('toast');

  window.clearTimeout(toastHideTimer);
  toast.textContent = normalizeToastMessage(message);

  toast.classList.remove('hidden');
}

function normalizeToastMessage(message) {
  const text = String(message || '').trim();

  if (/API HTTP\s+404/i.test(text) || /<!doctype html|<html[\s>]/i.test(text)) {
    return 'เชื่อมต่อ HRM API ไม่สำเร็จ: กรุณารีเฟรชหน้าและตรวจสอบ Apps Script Web App URL/deploy ล่าสุด';
  }

  return text;
}

function hideToast() {

  window.clearTimeout(toastHideTimer);
  toastHideTimer = setTimeout(() => {

    document
      .getElementById('toast')
      .classList.add('hidden');

  }, 700);
}

function showLoadingOverlay(message) {
  const overlay = document.getElementById('loadingOverlay');
  const text = document.getElementById('loadingOverlayText');
  if (text) text.textContent = message || 'กำลังโหลดข้อมูล...';
  if (overlay) overlay.classList.remove('hidden');
  document.body.classList.add('hrm-loading');
}

function hideLoadingOverlay() {
  document.getElementById('loadingOverlay')?.classList.add('hidden');
  document.body.classList.remove('hrm-loading');
}

/* =========================================
   UTIL
========================================= */

function escapeHtml(value) {

  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function escapeAttr(value) {

  return escapeHtml(value)
    .replaceAll('`', '');
}

function formatDateForInput(value) {

  return formatDateBEForSheet(value);
}

function formatDateForDisplay(value) {
  const d = parseDateValue(value);
  if (!d) return value || '';

  return `${d.getDate()} ${getThaiMonthName(d.getMonth())} ${d.getFullYear() + 543}`;
}

function formatBirthDate(emp) {
  const birthDate = parseDateValue(emp && emp.BIRTH_DATE);
  if (birthDate) return formatDateForDisplay(birthDate);

  const day = String(emp && emp.BIRTH_DAY || '').trim();
  const month = normalizeThaiMonth(emp && emp.BIRTH_MONTH);
  const year = String(emp && emp.BIRTH_YEAR_BE || '').trim();

  if (day && month && year) return `${day} ${month} ${year}`;

  const text = String(emp && emp.BIRTHDATE_TEXT || '').trim();
  const parsedText = parseDateValue(text);
  if (parsedText) return formatDateForDisplay(parsedText);

  return [day, month, year].filter(Boolean).join(' ') || text || '';
}

function formatBirthDateInput(emp) {
  const birthDate = parseDateValue(emp && emp.BIRTH_DATE);
  if (birthDate) return formatDateBEForSheet(birthDate);

  const textDate = parseDateValue(emp && emp.BIRTHDATE_TEXT);
  if (textDate) return formatDateBEForSheet(textDate);

  const day = String(emp && emp.BIRTH_DAY || '').trim();
  const monthIndex = getThaiMonthIndex(emp && emp.BIRTH_MONTH);
  const yearText = String(emp && emp.BIRTH_YEAR_BE || '').trim();
  if (day && monthIndex >= 0 && yearText) {
    let year = Number(yearText);
    if (year > 2400) year -= 543;
    return formatDateBEForSheet(new Date(year, monthIndex, Number(day)));
  }

  return String(emp && emp.BIRTHDATE_TEXT || '').trim();
}

function formatPersonType(value) {
  const text = normalizeFilterText(value).toUpperCase();
  if (text === 'LECTURER' || text === 'TEACHER' || text === 'ACADEMIC') return 'อาจารย์';
  if (text === 'STAFF' || text === 'SUPPORT') return 'เจ้าหน้าที่';
  return normalizeFilterText(value);
}

function formatWorkGroup(value) {
  const text = normalizeFilterText(value);
  if (text === 'อาจารย์' || text.toUpperCase() === 'LECTURER') return 'สายวิชาการ';
  if (text === 'เจ้าหน้าที่' || text.toUpperCase() === 'STAFF') return 'สายสนับสนุน';
  return text;
}

function normalizeThaiMonth(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';

  const months = [
    'มกราคม',
    'กุมภาพันธ์',
    'มีนาคม',
    'เมษายน',
    'พฤษภาคม',
    'มิถุนายน',
    'กรกฎาคม',
    'สิงหาคม',
    'กันยายน',
    'ตุลาคม',
    'พฤศจิกายน',
    'ธันวาคม'
  ];

  const num = parseInt(raw, 10);
  if (!isNaN(num) && num >= 1 && num <= 12) return months[num - 1];

  return raw;
}

function formatWorkTenure(startDate) {
  const start = parseDateValue(startDate);
  if (!start) return '-';

  const today = new Date();
  let years = today.getFullYear() - start.getFullYear();
  let months = today.getMonth() - start.getMonth();
  let days = today.getDate() - start.getDate();

  if (days < 0) {
    const prevMonthLastDay = new Date(today.getFullYear(), today.getMonth(), 0).getDate();
    days += prevMonthLastDay;
    months -= 1;
  }
  if (months < 0) {
    years -= 1;
    months += 12;
  }

  const parts = [];
  if (years > 0) parts.push(`${years} ปี`);
  if (months > 0) parts.push(`${months} เดือน`);
  if (days > 0 || !parts.length) parts.push(`${days} วัน`);

  return parts.join(' ');
}

function parseDateValue(value) {
  if (!value) return null;
  if (value instanceof Date && !isNaN(value)) return value;

  const raw = String(value).trim();
  let match = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (match) {
    let year = Number(match[1]);
    if (year > 2400) year -= 543;
    return new Date(year, Number(match[2]) - 1, Number(match[3]));
  }

  match = raw.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);
  if (match) {
    const year = Number(match[3]) > 2400 ? Number(match[3]) - 543 : Number(match[3]);
    return new Date(year, Number(match[2]) - 1, Number(match[1]));
  }

  match = raw.match(/^(\d{1,2})\s+([^\d\s]+)\s+(?:พ\.ศ\.|ค\.ศ\.)?\s*(\d{4})$/);
  if (match) {
    const month = getThaiMonthIndex(match[2]);
    if (month >= 0) {
      let year = Number(match[3]);
      if (year > 2400) year -= 543;
      return new Date(year, month, Number(match[1]));
    }
  }

  if (/[ก-ฮ]/.test(raw)) return null;

  const d = new Date(raw);
  return isNaN(d) ? null : d;
}

function getThaiMonthIndex(monthText) {
  const raw = String(monthText || '').trim();
  const aliases = [
    ['มกราคม', 'ม.ค.'],
    ['กุมภาพันธ์', 'ก.พ.'],
    ['มีนาคม', 'มี.ค.'],
    ['เมษายน', 'เม.ย.'],
    ['พฤษภาคม', 'พ.ค.'],
    ['มิถุนายน', 'มิ.ย.'],
    ['กรกฎาคม', 'ก.ค.'],
    ['สิงหาคม', 'ส.ค.'],
    ['กันยายน', 'ก.ย.'],
    ['ตุลาคม', 'ต.ค.'],
    ['พฤศจิกายน', 'พ.ย.'],
    ['ธันวาคม', 'ธ.ค.']
  ];
  return aliases.findIndex(items => items.indexOf(raw) !== -1);
}

function getThaiMonthName(monthIndex) {
  return [
    'มกราคม',
    'กุมภาพันธ์',
    'มีนาคม',
    'เมษายน',
    'พฤษภาคม',
    'มิถุนายน',
    'กรกฎาคม',
    'สิงหาคม',
    'กันยายน',
    'ตุลาคม',
    'พฤศจิกายน',
    'ธันวาคม'
  ][monthIndex] || '';
}

function joinParts(parts) {
  return (parts || [])
    .map(v => String(v || '').trim())
    .filter(Boolean)
    .join(' / ');
}

function normalizeFilterText(value) {
  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDepartment(value) {
  return normalizeFilterText(value)
    .replace(/ฯ/g, '')
    .replace(/^กลุ่มวิชา/g, '')
    .replace(/^สาขาวิชา/g, '')
    .replace(/^สาขา/g, '')
    .replace(/\s+/g, '');
}

function isDeanPosition(position) {
  return position === 'คณบดีคณะพยาบาลศาสตร์' || position === 'คณบดี';
}

function isHeadOfficePosition(position) {
  return position.indexOf('หัวหน้าสำนัก') === 0;
}

function getPersonnelGroup(emp) {
  const workGroup = formatWorkGroup(emp && emp.WORK_GROUP);
  if (workGroup === 'สายวิชาการ') return 'อาจารย์';
  if (workGroup === 'สายสนับสนุน') return 'เจ้าหน้าที่';

  const position = normalizeFilterText(emp && emp.POSITION);

  if (
    position === 'เจ้าหน้าที่' ||
    isHeadOfficePosition(position)
  ) {
    return 'เจ้าหน้าที่';
  }

  if (
    position === 'อาจารย์' ||
    isDeanPosition(position) ||
    position.indexOf('รองคณบดี') === 0 ||
    position === 'ผู้ช่วยคณบดี'
  ) {
    return 'อาจารย์';
  }

  return workGroup || position || '';
}

function isExecutivePerson(emp) {
  return isTrueValue(emp && emp.IS_EXECUTIVE);
}

function comparePersonnelPeople(a, b) {
  const execCompare = compareExecutivePeople(a, b);
  if (execCompare !== 0) return execCompare;

  const groupCompare = getGroupRank(a) - getGroupRank(b);
  if (groupCompare !== 0) return groupCompare;

  const dep = normalizeFilterText(a.DEPARTMENT).localeCompare(normalizeFilterText(b.DEPARTMENT), 'th');
  if (dep !== 0) return dep;

  return normalizeFilterText(a.FULL_NAME).localeCompare(normalizeFilterText(b.FULL_NAME), 'th');
}

function compareExecutivePeople(a, b) {
  const rank = getExecutiveRank(a) - getExecutiveRank(b);
  if (rank !== 0) return rank;
  return normalizeFilterText(a.FULL_NAME).localeCompare(normalizeFilterText(b.FULL_NAME), 'th');
}

function getGroupRank(emp) {
  if (isExecutivePerson(emp)) return 1;
  return getPersonnelGroup(emp) === 'อาจารย์' ? 2 : 3;
}

function getDisplayGroupTitle(emp, activeFilterGroup) {
  if (activeFilterGroup === 'EXECUTIVE') return 'คณะผู้บริหาร';
  if (activeFilterGroup === 'อาจารย์') return 'บุคลากรสายวิชาการ';
  if (activeFilterGroup === 'เจ้าหน้าที่') return 'บุคลากรสายสนับสนุน';
  if (isExecutivePerson(emp)) return 'คณะผู้บริหาร';
  return getPersonnelGroup(emp) === 'อาจารย์'
    ? 'บุคลากรสายวิชาการ'
    : 'บุคลากรสายสนับสนุน';
}

function getExecutiveRank(emp) {
  const position = normalizeFilterText(emp && emp.POSITION);
  if (isDeanPosition(position)) return 1;
  if (position.indexOf('รองคณบดีฝ่ายบริหาร') === 0) return 2;
  if (position.indexOf('รองคณบดีฝ่ายวิชาการ') === 0) return 3;
  if (position.indexOf('รองคณบดีฝ่ายกิจการ') === 0) return 4;
  if (position.indexOf('รองคณบดี') === 0) return 4;
  if (position === 'ผู้ช่วยคณบดี') return 5;
  if (isHeadOfficePosition(position)) return 6;

  const explicitOrder = getExplicitOrder(emp);
  if (explicitOrder < 999) return explicitOrder;
  return isExecutivePerson(emp) ? 50 : 999;
}

function getExplicitOrder(emp) {
  const raw = emp && (
    emp.EXECUTIVE_ORDER ||
    emp.DISPLAY_ORDER ||
    emp.ORDER ||
    emp.SORT_ORDER
  );
  const order = parseInt(raw, 10);
  return isNaN(order) ? 999 : order;
}

function isTrueValue(value) {
  if (value === true) return true;
  const text = normalizeFilterText(value).toUpperCase();
  return ['TRUE', 'YES', 'Y', '1', 'ใช่'].indexOf(text) !== -1;
}

function isPersonnelRecord(emp) {
  if (!normalizeFilterText(emp && (emp.PERSON_ID || emp.FULL_NAME || emp.EMAIL))) {
    return false;
  }

  const type = formatWorkGroup(emp && emp.WORK_GROUP).toLowerCase();
  const role = normalizeFilterText(emp && emp.ROLE).toLowerCase();
  const userType = normalizeFilterText(emp && emp.USER_TYPE).toLowerCase();
  const position = normalizeFilterText(emp && emp.POSITION).toLowerCase();
  const name = normalizeFilterText(emp && emp.FULL_NAME).toLowerCase();
  const blocked = ['bot', 'admin', 'admin ระบบ', 'ผู้ดูแลระบบ', 'แอดมินระบบ'];

  return !blocked.some(keyword =>
    type === keyword ||
    role === keyword ||
    userType === keyword ||
    position === keyword ||
    name === keyword
  );
}

function renderDetailSection(title, items) {
  const html = (items || []).map(item => {
    const label = item[0];
    const value = item[1] || '-';

    return `
      <div class="detail-item">
        <span class="detail-label">${escapeHtml(label)}</span>
        <div class="detail-value">${escapeHtml(value)}</div>
      </div>
    `;
  }).join('');

  return `
    <section class="detail-section">
      <h3>${escapeHtml(title)}</h3>
      <div class="detail-grid">${html}</div>
    </section>
  `;
}

function renderDetailRowsSection(title, rows) {
  const sideBySideTitles = ['ข้อมูลพนักงาน', 'ใบประกอบวิชาชีพ'];
  const sectionClass = [
    sideBySideTitles.includes(title) ? 'detail-section--side-by-side' : '',
    title === 'ข้อมูลเฉพาะอาจารย์' ? 'detail-section--stacked-pairs' : ''
  ].filter(Boolean).join(' ');
  const sectionClassAttr = sectionClass ? ` ${sectionClass}` : '';
  const html = (rows || []).map(row => {
    const cols = Math.min(Math.max((row || []).length, 1), 4);
    const items = (row || []).map(item => {
      const label = item[0];
      const value = item[1] || '-';

      return `
        <div class="detail-item">
          <span class="detail-label">${escapeHtml(label)}</span>
          <div class="detail-value">${escapeHtml(value)}</div>
        </div>
      `;
    }).join('');

    return `<div class="detail-row detail-row-${cols}">${items}</div>`;
  }).join('');

  return `
    <section class="detail-section${sectionClassAttr}">
      <h3>${escapeHtml(title)}</h3>
      <div class="detail-rows">${html}</div>
    </section>
  `;
}

function getEducationTableRows(emp) {
  return getEducationRowsFromEmployee(emp)
    .filter(educationRowHasContent)
    .map(row => [
      getEducationLevelLabel(row.level),
      row.degree,
      row.major,
      row.institution,
      row.year
    ]);
}

